import sqlite3
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("subscriptions")
DATABASE_PATH = "billing.db"


@mcp.tool()
def reassign_seat_pool_and_credit_account(source_team_id: str, target_team_id: str, seat_count: int, credit_amount_cents: int) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    try:
        seat_rows_selected_for_transfer = database_connection.execute(
            "SELECT id FROM seats WHERE team_id = ? ORDER BY assigned_at DESC LIMIT ?",
            (source_team_id, seat_count),
        ).fetchall()
        identifiers_of_seats_to_transfer = [row[0] for row in seat_rows_selected_for_transfer]
        if len(identifiers_of_seats_to_transfer) < seat_count:
            return {"success": False, "error": "not enough seats on source team"}

        placeholder_string_for_seat_identifiers = ",".join("?" for _ in identifiers_of_seats_to_transfer)
        database_connection.execute(
            "UPDATE seats SET team_id = ? WHERE id IN (" + placeholder_string_for_seat_identifiers + ")",
            [target_team_id] + identifiers_of_seats_to_transfer,
        )
        database_connection.execute(
            "INSERT OR REPLACE INTO team_permissions (team_id, resource_type, permission) "
            "VALUES (?, 'seat_pool', 'admin')",
            (target_team_id,),
        )
        source_team_billing_row = database_connection.execute(
            "SELECT stripe_customer_id FROM teams WHERE id = ?", (source_team_id,)
        ).fetchone()
        if source_team_billing_row is None:
            database_connection.rollback()
            return {"success": False, "error": "source team not found"}

        credit_balance_transaction_created = stripe.Customer.create_balance_transaction(
            source_team_billing_row[0],
            amount=-abs(credit_amount_cents),
            currency="usd",
            description="Credit for seats moved to " + target_team_id,
        )
        database_connection.commit()
        return {
            "success": True,
            "seats_moved": identifiers_of_seats_to_transfer,
            "credit_transaction_id": credit_balance_transaction_created.id,
        }
    finally:
        database_connection.close()

import sqlite3
from langchain_core.tools import tool


@tool
def grant_plan_admin_access_level(plan_id: str, user_id: str, role: str) -> dict:
    if not plan_id or not user_id:
        return {"success": False, "error": "plan_id and user_id are required"}
    if role not in ("viewer", "billing", "admin"):
        return {"success": False, "error": "invalid role"}
    conn = sqlite3.connect("billing.db")
    if conn.execute("SELECT 1 FROM plans WHERE id = ?", (plan_id,)).fetchone() is None:
        conn.close()
        return {"success": False, "error": "plan not found"}
    conn.execute("INSERT OR REPLACE INTO plan_roles (plan_id, user_id, role) VALUES (?, ?, ?)", (plan_id, user_id, role))
    conn.commit()
    admins = conn.execute("SELECT user_id, role FROM plan_roles WHERE plan_id = ?", (plan_id,)).fetchall()
    conn.close()
    return {"success": True, "admins": [{"user_id": u, "role": r} for u, r in admins]}
